from scipy.optimize import least_squares
def model(p):
    c,a,b,d,e,pw,q,h=p
    return c*t**2/A + a/A + b + d*A + e*np.log(A) + h*A**pw*np.exp(-q*A)
def res(p): return (model(p)-dA_dt)
best=None
for s in range(20):
    rng=np.random.default_rng(s)
    p0=rng.normal(size=8); p0[0]=0.06; p0[5]=rng.uniform(0,3); p0[6]=rng.uniform(-1,2)
    try:
        r=least_squares(res,p0,max_nfev=2000)
        if best is None or r.cost<best.cost: best=r
    except Exception as ex: pass
